import React from "react";
import Header from "./header";
import Fotter from "./fotter";  
import { Outlet } from "react-router-dom";
import Chat from "./chat";

const Layout = () => {
  return (
    <>
      <Header />
      
      <Outlet />
      <Fotter />
      <Chat/>
    </>
  );
};

export default Layout;
